/bin/bash -lc "python - <<'PY'
import numpy as np
from sim import Sim

qg=np.array([ 0.465,  0.767, -0.991, -1.194, -1.792,  3.578,  1.374])
ql=np.array([-0.388,  1.123,  1.851, -0.415, -0.903,  2.032,  2.743])
for grip in [200,160,120,80,40,20,10,0]:
    sim=Sim(); d=sim.data
    def step(q,g):
        d.ctrl[:7]=q; d.ctrl[7]=g; d.ctrl[8]=1.0; sim.step(1)
    def interp(q0,q1,n,g0,g1):
        for i in range(n):
            a=(i+1)/n; step((1-a)*q0+a*q1,(1-a)*g0+a*g1)
    q0=d.qpos[:7].copy()
    for _ in range(300): step(q0,255)
    interp(q0,qg,900,255,220)
    for _ in range(150): step(qg,220)
    # set desired grip and hold
    interp(qg,qg,300,220,grip)
    for _ in range(100): step(qg,grip)
    c_before=sim.has_gripper_block_contact(); b_before=sim.block_position().copy()
    interp(qg,ql,1000,grip,grip)
    for _ in range(300): step(ql,grip)
    b=sim.block_position().copy(); c=sim.has_gripper_block_contact()
    print('grip',grip,'before',np.round(b_before,3),c_before,'after',np.round(b,3),c,'zmax',round(float(np.max(np.array([t[2] for t in np.array([e[\"block_pos\"] if isinstance(e,dict) else None for e in []])))),3) if False else '')
PY"

